public class Payroll {

    public static double totalPayroll(Employee[] staff) {
        double total = 0.0;
        for (Employee employee : staff) {
            total += employee.pay();
        }
        return total;
    }

    public static Employee highestPaid(Employee[] staff) {
        Employee best = null;
        for (Employee employee : staff) {
            if (best == null || employee.pay() > best.pay()) {
                best = employee;
            }
        }
        return best;
    }
}

