public class PayrollTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Manager dana = new Manager("Dana", 80000.0, 15000.0);
        check("manager pay includes the bonus", 95000.0, dana.pay());
        check("manager keeps its name", "Dana", dana.getName());
        check("manager base salary is unchanged", 80000.0, dana.getBaseSalary());
        Employee[] staff = {
            new Employee("Ann", 50000.0),
            dana,
            new Employee("Bob", 62000.0)
        };
        check("totalPayroll over three employees", 207000.0, Payroll.totalPayroll(staff));
        Employee top = Payroll.highestPaid(staff);
        check("highestPaid finds the manager", "Dana", top == null ? null : top.getName());
        Employee[] tie = { new Employee("First", 40000.0), new Employee("Second", 40000.0) };
        Employee tieWinner = Payroll.highestPaid(tie);
        check("highestPaid keeps the first of a tie", "First", tieWinner == null ? null : tieWinner.getName());
        check("totalPayroll of an empty array", 0.0, Payroll.totalPayroll(new Employee[0]));
        check("highestPaid of an empty array", null, Payroll.highestPaid(new Employee[0]));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

